    const len = big ? n : r.int(1, n);
    const path = [0, ...rest.slice(0, len - 1)], off = rest.slice(len - 1);
    const next = new Array(n).fill(-1);
    for (let i = 0; i + 1 < path.length; i++) next[path[i]] = path[i + 1];
