function hasLoop(next: number[]): boolean {
  let slow = 0, fast = 0;
  while (fast !== -1 && next[fast] !== -1) {
    slow = next[slow];
    fast = next[next[fast]];
    if (slow === fast) return true;
  }
  return false;
}

